export function defaultCommerceSettings(category: StoreCategory): CommerceSettings {
  const tech = category === "tech";
  const luxury = category === "fashion" || category === "accessories" || category === "beauty";
  return {
    priceStyle: tech ? "techSpec" : luxury ? "luxuryInline" : "standard",
    cardStyle: tech ? "retail" : luxury ? "editorial" : "softCard",
    imageRatio: luxury ? "editorial" : tech ? "square" : "portrait",
    showRatings: tech || category === "food" || category === "beauty",
    showSwatches: category === "fashion" || category === "shoes" || category === "accessories",
    showBadges: true,
    quickView: true,
    wishlist: luxury,
    mediaBehavior: luxury ? "hoverZoom" : "static",
  };
}

export function sectionStrategy(category: StoreCategory, archetype: CommerceArchetype): SectionSpec[] {
  const id = () => crypto.randomUUID();
  const productFirst = archetype === "conversion" || archetype === "catalog" || archetype === "tech-retail";
  const editorial = archetype === "editorial" || archetype === "luxury" || archetype === "magazine" || archetype === "storytelling";
  const campaign = archetype === "campaign" || archetype === "streetwear" || archetype === "dark-premium";

  const products: SectionSpec = { id: id(), type: "products", eyebrow: category === "tech" ? "Popular devices" : "Featured products", variant: productFirst ? "rail" : "editorial" };
  const collections: SectionSpec = { id: id(), type: "collections", eyebrow: "Shop by collection", variant: editorial ? "editorial" : "clean" };
  const story: SectionSpec = { id: id(), type: "story", eyebrow: editorial ? "Editorial story" : "Why it works", variant: editorial ? "editorial" : "split" };
  const features: SectionSpec = { id: id(), type: "features", eyebrow: "Why shop with us", variant: "cards" };
  const quote: SectionSpec = { id: id(), type: "quote", eyebrow: "Point of view", variant: "editorial" };
  const promo: SectionSpec = { id: id(), type: "campaign", eyebrow: "Limited campaign", variant: "contrast" };
  const comparison: SectionSpec = { id: id(), type: "comparison", eyebrow: "Compare the edit", variant: "cards" };
  const social: SectionSpec = { id: id(), type: "socialProof", eyebrow: "Seen in the wild", variant: "rail" };
  const video: SectionSpec = { id: id(), type: "videoStory", eyebrow: "In motion", variant: "immersive" };
  const testimonials: SectionSpec = { id: id(), type: "testimonials", eyebrow: "Customer notes", variant: "cards" };
  const faq: SectionSpec = { id: id(), type: "faq", eyebrow: "Good to know", variant: "minimal" };
  const newsletter: SectionSpec = { id: id(), type: "newsletter", eyebrow: "Stay connected", variant: "clean" };

  if (productFirst) return [products, collections, features, comparison, testimonials, faq, newsletter];
  if (campaign) return [collections, promo, products, video, social, testimonials, newsletter];
  if (editorial) return [story, collections, products, quote, social, newsletter];
  return [collections, products, features, story, testimonials, faq, newsletter];
}
